import{_ as e}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as o,o as a,af as i}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const b=JSON.parse('{"title":"Pi Agent 设计哲学","description":"极简代码 Agent 的「不做什么」清单：四个 API、四个工具、不到 1000 token 的系统提示，以及用文件与 CLI 替代内置功能的取舍。","frontmatter":{"title":"Pi Agent 设计哲学","description":"极简代码 Agent 的「不做什么」清单：四个 API、四个工具、不到 1000 token 的系统提示，以及用文件与 CLI 替代内置功能的取舍。","domain":"tech","tags":["tech","course-notes","legacy","agent","minimalism"],"navOrder":81,"topicId":"course-notes-pi-agent","layer":"appendix","status":"legacy","nodeType":"resource","owner":"learn-ai","lastVerified":"2026-09-01","listed":true},"headers":[],"relativePath":"zh/tech/appendices/course-notes/pi-agent-design-philosophy.md","filePath":"zh/tech/appendices/course-notes/pi-agent-design-philosophy.md","lastUpdated":1791116096000}'),n={name:"zh/tech/appendices/course-notes/pi-agent-design-philosophy.md"};function r(d,t,s,l,h,p){return a(),o("div",null,[...t[0]||(t[0]=[i('<h1 id="pi-agent-设计哲学" tabindex="-1">Pi Agent 设计哲学 <a class="header-anchor" href="#pi-agent-设计哲学" aria-label="Permalink to &quot;Pi Agent 设计哲学&quot;">​</a></h1><blockquote><p>源码：<a href="https://github.com/badlogic/pi-mono" target="_blank" rel="noreferrer">badlogic/pi-mono</a>，来自 @badlogic 的博客文章。文中数字（token 数、工具数、基准名次）归属原文。</p></blockquote><h2 id="核心观点" tabindex="-1">核心观点 <a class="header-anchor" href="#核心观点" aria-label="Permalink to &quot;核心观点&quot;">​</a></h2><p>构建 Agent 的核心理念：<strong>&quot;如果我不需要它，它就不会被构建。&quot;</strong> Pi 是一个极简代码 Agent，专注控制感与可观测性，而非功能堆砌。</p><h2 id="pi-ai-统一-llm-api" tabindex="-1">pi-ai：统一 LLM API <a class="header-anchor" href="#pi-ai-统一-llm-api" aria-label="Permalink to &quot;pi-ai：统一 LLM API&quot;">​</a></h2><ul><li><strong>四大 API 搞定一切</strong>：OpenAI Chat / OpenAI Responses / Anthropic Messages / Google Generative AI</li><li><strong>Context Handoff</strong>：为跨 Provider 上下文迁移设计（如 Anthropic 的 thinking traces 迁移到 OpenAI 时转为 <code>&lt;thinking&gt;</code> 文本标签）</li><li><strong>Structured Split Tool Results</strong>：Tool 返回拆为 LLM 部分（纯文本/JSON）与 UI 部分（结构化数据 + 附件），UI 渲染与 LLM 上下文各取所需</li><li><strong>极简 Agent Loop</strong>：不提供 max steps 参数，循环直到模型输出非 Tool Call 响应</li></ul><h2 id="pi-coding-agent-极简代码-agent" tabindex="-1">pi-coding-agent：极简代码 Agent <a class="header-anchor" href="#pi-coding-agent-极简代码-agent" aria-label="Permalink to &quot;pi-coding-agent：极简代码 Agent&quot;">​</a></h2><p><strong>极简 System Prompt + 四个工具</strong>（整个 System Prompt + Tools 不到 1000 tokens）：</p><table tabindex="0"><thead><tr><th>工具</th><th>用途</th></tr></thead><tbody><tr><td><code>read</code></td><td>读取文件内容</td></tr><tr><td><code>write</code></td><td>创建/覆盖文件</td></tr><tr><td><code>edit</code></td><td>精确替换（oldText 必须完全匹配）</td></tr><tr><td><code>bash</code></td><td>执行命令行</td></tr></tbody></table><p><strong>YOLO by Default</strong>：默认无权限检查、无安全护栏。作者观点：一旦 Agent 能写代码并执行代码，「安全护栏」基本是安全 theater；真正的保护是网络/容器隔离。</p><p><strong>不做这些（Opinionated No）</strong>：</p><table tabindex="0"><thead><tr><th>不做的功能</th><th>原因与替代</th></tr></thead><tbody><tr><td>内置 To-Do</td><td>增加模型需跟踪的状态 → 用 <code>TODO.md</code> 文件</td></tr><tr><td>Plan Mode</td><td>自然语言协作够了 → 持久规划写 <code>PLAN.md</code></td></tr><tr><td>MCP 支持</td><td>MCP Server 太大（原文举例：21 工具 / 13.7k tokens）→ 用带 README 的 CLI 工具按需加载</td></tr><tr><td>后台 Bash</td><td>→ 用 tmux</td></tr><tr><td>Sub-Agent</td><td>→ 用 bash 启动新 pi session</td></tr></tbody></table><h2 id="pi-tui-追加模式-ui" tabindex="-1">pi-tui：追加模式 UI <a class="header-anchor" href="#pi-tui-追加模式-ui" aria-label="Permalink to &quot;pi-tui：追加模式 UI&quot;">​</a></h2><p>两种 TUI 模式：全屏模式（接管终端视口，代表 Amp、opencode）vs 追加模式（像普通 CLI 追加内容，代表 Claude Code、Codex、pi）。Pi 选追加模式，复用终端原生滚动与搜索；差分渲染（找到第一行差异处从那里重绘）+ ANSI 同步输出序列防闪烁。</p><h2 id="关键设计原则" tabindex="-1">关键设计原则 <a class="header-anchor" href="#关键设计原则" aria-label="Permalink to &quot;关键设计原则&quot;">​</a></h2><ol><li><strong>控制 &gt; 功能</strong>：保持对所有交互的完全可观测性</li><li><strong>极简 &gt; 堆砌</strong>：不加不需要的功能</li><li><strong>Token 效率</strong>：渐进式上下文加载，避免 context rot</li><li><strong>YOLO 信任</strong>：默认信任用户，用容器做隔离</li><li><strong>工具即 CLI</strong>：不用 MCP，用带 README 的命令行工具按需加载</li></ol><h2 id="与主线的关系" tabindex="-1">与主线的关系 <a class="header-anchor" href="#与主线的关系" aria-label="Permalink to &quot;与主线的关系&quot;">​</a></h2><p>「极简工具集够用」「上下文渐进加载」的观点与主线 <a href="/zh/tech/06-agent-systems/agent-runtime.html">Agent 运行时</a>、<a href="/zh/tech/03-context/context-engineering.html">上下文工程</a>互为印证；其 MCP 取舍是单作者立场，与主线 <a href="/zh/tech/07-interoperability/mcp.html">MCP</a> 的协议视角对照阅读更有价值。</p>',18)])])}const A=e(n,[["render",r]]);export{b as __pageData,A as default};
